import unittest
import os
from vcenter_ops import find_datacenter

class TestVCenterIntegration(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        # Dynamically read connection parameters from environment variables or default to localhost
        cls.host = os.getenv("VCENTER_HOST", "127.0.0.1:8989")
        cls.user = os.getenv("VCENTER_USER", "user")
        cls.password = os.getenv("VCENTER_PASSWORD", "pass")

    def test_find_default_datacenter_success(self):
        """Integration test: Verify the default 'DC0' datacenter generated by vcsim exists."""
        result = find_datacenter(
            host=self.host,
            user=self.user,
            password=self.password,
            dc_name="DC0" # vcsim auto-creates 'DC0' by default
        )
        self.assertTrue(result, "Integration test failed: Expected Datacenter 'DC0' was not found.")

    def test_find_datacenter_not_found(self):
        """Integration test: Verify that searching for a non-existent datacenter returns False."""
        result = find_datacenter(
            host=self.host,
            user=self.user,
            password=self.password,
            dc_name="NonExistent-DC"
        )
        self.assertFalse(result, "Integration test failed: Found a datacenter that shouldn't exist.")

if __name__ == '__main__':
    unittest.main()
